  if task_row.budget_scope_id is null then update turn_private.service_tasks set budget_scope_id=p.scope_id where id=c.task_id and budget_scope_id is null;if not found then raise exception 'EXECUTION_PROFILE_CONFLICT';end if;end if;
  execution_id:=coalesce(r.id,gen_random_uuid());
  e:=jsonb_build_object('schemaVersion','planning-v2-execution/1','executionId',execution_id,'profileId',p.id,'profileRevision',p.revision,'textPolicyId',p.text_policy_id,'scopeId',p.scope_id,'provider','qwen','model',tar.model,'providerConfigurationId',p.provider_configuration_id,'providerConfigurationVersion',p.provider_configuration_version,'endpoint',p.endpoint,'priceVersion',tar.price_version,'reservedMicros',p.reserved_micros,'timeoutMs',p.timeout_ms,'maxOutputTokens',p.max_output_tokens,'inputMicrosPerMillion',tar.input_rate,'cachedInputMicrosPerMillion',tar.cached_input_rate,'outputMicrosPerMillion',tar.output_rate,'maxMapCalls',13,'maxSteps',4,'maxRetries',0,'deadlineMs',120000);
  source:=(q->'qualifiedIntake')-array['version','kind','schemaVersion','sourceKind','intake','contextDigest','readiness','readyForProvider'];
  if r.id is null then
    insert into turn_private.planning_v2_execution_runs(id,profile_id,profile_revision,owner_id,task_id,turn_id,original_lease,source,intake_digest,planning_digest,collector_principal_id,origin_kind,execution,profile_snapshot) values(execution_id,p.id,p.revision,p_owner_id,c.task_id,c.turn_id,w.lease_token,source,q->>'intakeContextDigest',q->>'planningContextDigest',p.collector_principal_id,origin,e,to_jsonb(p));
  else
    if r.execution is distinct from e or r.intake_digest<>q->>'intakeContextDigest' or r.planning_digest<>q->>'planningContextDigest' then raise exception 'STALE_BASIS';end if;
  end if;
  return jsonb_build_object('kind','leased','lease',jsonb_build_object('ownerId',p_owner_id,'taskId',c.task_id,'turnId',c.turn_id,'leaseToken',w.lease_token,'artifactId',c.artifact_id,'planningPolicyId',p.planning_policy_id,'intakeContextDigest',q->>'intakeContextDigest','planningContextDigest',q->>'planningContextDigest','source',source,'environment',p.environment,'locale',c.locale),'execution',e);
 end loop;
 return jsonb_build_object('kind','idle');
exception when lock_not_available then return jsonb_build_object('kind','blocked');
end $function$

turn_private.cancel_chat_turn_unmetered(:
CREATE OR REPLACE FUNCTION turn_private.cancel_chat_turn_unmetered(p_turn_id uuid)
 RETURNS TABLE(sequence integer, state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  turn_row public.turns%rowtype;
  prior_sequence integer;
  cancel_sequence integer;
begin PERFORM identity_private.guard_mobile_rpc_v2();
  select * into turn_row from public.turns where id = p_turn_id and owner_id = (select auth.uid()) for update;
  if not found or turn_row.thread_id is null or not exists (
    select 1 from public.chat_threads where id = turn_row.thread_id and owner_id = (select auth.uid()) and status = 'active'
  ) then raise exception 'FORBIDDEN'; end if;
  select e.sequence into cancel_sequence from public.chat_turn_events e where e.turn_id = p_turn_id and e.state = 'cancelled' limit 1;
  if cancel_sequence is not null then return query select cancel_sequence, 'cancelled'::text; return; end if;
  if turn_row.status in ('completed', 'proposal_ready', 'unavailable', 'failed') then raise exception 'terminal turn cannot emit events'; end if;
  select e.sequence into prior_sequence from public.chat_turn_events e where e.turn_id = p_turn_id order by e.sequence desc limit 1;
  insert into public.chat_turn_events(owner_id, thread_id, turn_id, event_id, sequence, schema_version, event_type, state)
    values (turn_row.owner_id, turn_row.thread_id, p_turn_id, 'cancelled', prior_sequence + 1, 'turn-sse-v1', 'terminal', 'cancelled');
  update public.turns set status = 'cancelled', updated_at = now() where id = p_turn_id;
  update public.chat_threads set updated_at = now() where id = turn_row.thread_id;
  return query select prior_sequence + 1, 'cancelled'::text;
end;
$function$

claim_scoped_trip_edit_work_v1(uuid,uuid:
CREATE OR REPLACE FUNCTION public.claim_scoped_trip_edit_work_v1(p_owner_id uuid, p_policy_id uuid, p_scope_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare w turn_private.work%rowtype;j scoped_edit_private.work_v1%rowtype;c scoped_edit_private.contexts_v1%rowtype;cfg scoped_edit_private.worker_settings_v1%rowtype;b jsonb;begin
 if auth.role() is distinct from 'service_role' or p_owner_id is null or p_policy_id is null or p_scope_id is null then raise exception 'FORBIDDEN';end if;
 if not scoped_edit_private.worker_policy_v1(p_owner_id,p_policy_id,p_scope_id) then return jsonb_build_object('kind','pending');end if;
 for j in select * from scoped_edit_private.work_v1 where owner_id=p_owner_id and policy_id=p_policy_id and scope_id=p_scope_id and paused_reason is null order by turn_id loop
 select * into c from scoped_edit_private.contexts_v1 where id=j.context_id;if not found or not scoped_edit_private.service_current_v1(c) then continue;end if;
 if not turn_private.lock_turn(j.turn_id,j.owner_id,(c.actor_basis->>'sessionId')::uuid) then continue;end if;
 select * into w from turn_private.work where turn_id=j.turn_id and execution_mode='scoped_trip_edit_v1' and (state='queued' or state='leased' and expires_at<=clock_timestamp()) for update skip locked;
 if not found or w.attempt>=w.max_attempts then continue;end if;
 select * into cfg from scoped_edit_private.worker_settings_v1 where policy_id=j.policy_id;
 update turn_private.work set state='leased',attempt=attempt+1,lease_token=gen_random_uuid(),expires_at=least(clock_timestamp()+lease_ms*interval '1 millisecond',c.expires_at) where turn_id=w.turn_id returning * into w;
 b:=jsonb_build_object('ownerId',j.owner_id,'taskId',j.task_id,'turnId',j.turn_id,'leaseToken',w.lease_token,'operationId',j.operation_id,'contextId',c.id,'contextDigest',c.digest,'sourceDigest',c.source_basis->'sourceDigest','tripId',c.trip_id,'baseVersion',c.base_version,'policyId',j.policy_id,'scopeId',j.scope_id,'attemptId',j.attempt_id,'provider','qwen','model',cfg.model,'priceVersion',cfg.price_version);
 update scoped_edit_private.work_v1 set binding=b,completion=case when completion is null then null else completion||jsonb_build_object('binding',b) end where turn_id=j.turn_id;
 return jsonb_build_object('kind','leased','ownerId',j.owner_id,'turnId',j.turn_id,'attempt',w.attempt,'leaseToken',w.lease_token,'leaseMs',w.lease_ms);
 end loop;return jsonb_build_object('kind','idle');
end $function$

